/* C API of the Rust port of `int_pow.c`, generated by rust-anything. */
#ifndef INT_POW_RS_H
#define INT_POW_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t int_pow(uint64_t base, unsigned int exp);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_int_pow(uint64_t base, unsigned int exp);

#endif /* INT_POW_RS_H */
